def forward(apps, schema_editor):
    """A "deadline.reminder" subscription becomes the two reminders it used to send (7 days and 1 day before); a "submission.published"
    subscription for every module becomes one per filing module, which the settings page now lists one by one."""
    Subscription = apps.get_model("notifications", "Subscription")
    DeadlineReminder = apps.get_model("notifications", "DeadlineReminder")
    for s in Subscription.objects.filter(event="deadline.reminder"):
        for days in REMINDER_DAYS:
            DeadlineReminder.objects.get_or_create(user_id=s.user_id, module=s.module, days_before=days, defaults={"channel": s.channel})
        s.delete()
